window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dbdc6dfafafd9f60"]={"versions": [{"id": "FIG-dbdc6dfafafd9f60", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses des Prüfschritts <code>E2E_P02_handle_wrongSequence</code> innerhalb der Empfängerprüfung des AUTOSAR E2E-Profils 2 (<code>E2E_P02Check</code>). Das Diagramm spezifiziert die Aktualisierung des internen E2E-Zustands (<code>E2E_P02CheckStateType</code>) bei Auftreten einer fehlerhaften Sequenz (z. B. Sequenzsprung oder Zählerdiskrepanz) unter Berücksichtigung von Konfigurationsparametern (<code>E2E_P02ConfigType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsvariablen / Parameter:</strong></li>\n<li><code>ReceivedCounter</code>: Aus den empfangenen Nutzdaten extrahierter Sequenzzähler.</li>\n<li><code>Config-&gt;SyncCounterInit</code>: Konfigurierter Initialwert für den Synchronisationszähler.</li>\n<li><code>Config-&gt;MaxDeltaCounterInit</code>: Konfigurierter Initialwert für die Begrenzung des maximalen Zählerdeltas.</li>\n<li><strong>Zustandsvariablen (<code>State</code>):</strong></li>\n<li><code>State-&gt;NoNewOrRepeatedDataCounter</code>: Zähler für fehlende oder wiederholte Datenrahmen.</li>\n<li><code>State-&gt;SyncCounter</code>: Zähler für aufeinanderfolgende Synchronisationszyklen.</li>\n<li><code>State-&gt;MaxDeltaCounter</code>: Zähler zur Verfolgung erlaubter Sequenzsprünge.</li>\n<li><code>State-&gt;LastValidCounter</code>: Zuletzt als gültig akzeptierter Sequenzzählerstand.</li>\n<li><strong>Kernelemente:</strong></li>\n<li>Initialknoten, vier Aktionsblöcke (Zuweisungen), ein Verzweigungsknoten (Decision Node) mit Guard-Bedingung, ein Zusammenführungsknoten (Merge Node) sowie ein Endknoten (Activity Final).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start:</strong> Der Ablauf beginnt am Initialknoten beim Eintritt in die Fehlerbehandlung für ungültige Sequenzen.</li>\n<li><strong>Rücksetzen des Datenzählers:</strong> <code>State-&gt;NoNewOrRepeatedDataCounter</code> wird auf <code>0</code> gesetzt.</li>\n<li><strong>Initialisierung des Sync-Zählers:</strong> <code>State-&gt;SyncCounter</code> wird mit <code>Config-&gt;SyncCounterInit</code> initialisiert.</li>\n<li><strong>Bedingungsprüfung:</strong> Prüfung der Bedingung <code>State-&gt;SyncCounter &gt; 0</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zweig <code>[TRUE]</code>:</strong></li>\n<li><code>State-&gt;MaxDeltaCounter</code> wird auf <code>Config-&gt;MaxDeltaCounterInit</code> gesetzt.</li>\n<li><code>State-&gt;LastValidCounter</code> wird auf den aktuellen <code>ReceivedCounter</code> gesetzt.</li>\n<li>Der Kontrollfluss wird zum Zusammenführungsknoten geführt.</li>\n<li><strong>Zweig <code>[FALSE]</code>:</strong></li>\n<li>Das Setzen von <code>MaxDeltaCounter</code> und <code>LastValidCounter</code> wird übersprungen; der Pfad führt direkt zum Zusammenführungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Der Kontrollfluss verlässt die Zusammenführung und erreicht den Endknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der Ablauf bildet einen normativen Teilschritt der Funktion <code>E2E_P02Check</code> ab und muss exakt wie abgebildet implementiert werden, um konforme E2E-Zustandsübergänge bei Sequenzfehlern sicherzustellen.</li>\n<li>Die bedingte Aktualisierung von <code>LastValidCounter</code> verhindert, dass bei unvollständiger oder deaktivierter Resynchronisation (<code>SyncCounter == 0</code>) der Referenzzähler für Folgeprüfungen ungültig überschrieben wird.</li>\n<li>Typische Implementierungsfalle: Zuweisung von <code>LastValidCounter</code> außerhalb des <code>[TRUE]</code>-Zweigs, was zu fehlerhaften Delta-Berechnungen in nachfolgenden Prüfzyklen führen würde.</li>\n</ul>"}, {"id": "FIG-11d27b7d197d5d54", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des internen Kontrollflusses des Prüfschritts <code>E2E_P02_handle_wrongSequence</code> innerhalb der Empfängerprüfung des AUTOSAR E2E-Profils 2 (<code>E2E_P02Check</code>). Das Diagramm spezifiziert die Aktualisierung des internen E2E-Zustands (<code>E2E_P02CheckStateType</code>) bei Auftreten einer fehlerhaften Sequenz (z. B. Sequenzsprung oder Zählerdiskrepanz) unter Berücksichtigung von Konfigurationsparametern (<code>E2E_P02ConfigType</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsvariablen / Parameter:</strong></li>\n<li><code>ReceivedCounter</code>: Aus den empfangenen Nutzdaten extrahierter Sequenzzähler.</li>\n<li><code>Config-&gt;SyncCounterInit</code>: Konfigurierter Initialwert für den Synchronisationszähler.</li>\n<li><code>Config-&gt;MaxDeltaCounterInit</code>: Konfigurierter Initialwert für die Begrenzung des maximalen Zählerdeltas.</li>\n<li><strong>Zustandsvariablen (<code>State</code>):</strong></li>\n<li><code>State-&gt;NoNewOrRepeatedDataCounter</code>: Zähler für fehlende oder wiederholte Datenrahmen.</li>\n<li><code>State-&gt;SyncCounter</code>: Zähler für aufeinanderfolgende Synchronisationszyklen.</li>\n<li><code>State-&gt;MaxDeltaCounter</code>: Zähler zur Verfolgung erlaubter Sequenzsprünge.</li>\n<li><code>State-&gt;LastValidCounter</code>: Zuletzt als gültig akzeptierter Sequenzzählerstand.</li>\n<li><strong>Kernelemente:</strong></li>\n<li>Initialknoten, vier Aktionsblöcke (Zuweisungen), ein Verzweigungsknoten (Decision Node) mit Guard-Bedingung, ein Zusammenführungsknoten (Merge Node) sowie ein Endknoten (Activity Final).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Start:</strong> Der Ablauf beginnt am Initialknoten beim Eintritt in die Fehlerbehandlung für ungültige Sequenzen.</li>\n<li><strong>Rücksetzen des Datenzählers:</strong> <code>State-&gt;NoNewOrRepeatedDataCounter</code> wird auf <code>0</code> gesetzt.</li>\n<li><strong>Initialisierung des Sync-Zählers:</strong> <code>State-&gt;SyncCounter</code> wird mit <code>Config-&gt;SyncCounterInit</code> initialisiert.</li>\n<li><strong>Bedingungsprüfung:</strong> Prüfung der Bedingung <code>State-&gt;SyncCounter &gt; 0</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zweig <code>[TRUE]</code>:</strong></li>\n<li><code>State-&gt;MaxDeltaCounter</code> wird auf <code>Config-&gt;MaxDeltaCounterInit</code> gesetzt.</li>\n<li><code>State-&gt;LastValidCounter</code> wird auf den aktuellen <code>ReceivedCounter</code> gesetzt.</li>\n<li>Der Kontrollfluss wird zum Zusammenführungsknoten geführt.</li>\n<li><strong>Zweig <code>[FALSE]</code>:</strong></li>\n<li>Das Setzen von <code>MaxDeltaCounter</code> und <code>LastValidCounter</code> wird übersprungen; der Pfad führt direkt zum Zusammenführungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Der Kontrollfluss verlässt die Zusammenführung und erreicht den Endknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der Ablauf bildet einen normativen Teilschritt der Funktion <code>E2E_P02Check</code> ab und muss exakt wie abgebildet implementiert werden, um konforme E2E-Zustandsübergänge bei Sequenzfehlern sicherzustellen.</li>\n<li>Die bedingte Aktualisierung von <code>LastValidCounter</code> verhindert, dass bei unvollständiger oder deaktivierter Resynchronisation (<code>SyncCounter == 0</code>) der Referenzzähler für Folgeprüfungen ungültig überschrieben wird.</li>\n<li>Typische Implementierungsfalle: Zuweisung von <code>LastValidCounter</code> außerhalb des <code>[TRUE]</code>-Zweigs, was zu fehlerhaften Delta-Berechnungen in nachfolgenden Prüfzyklen führen würde.</li>\n</ul>"}], "trans": [{"from": "FIG-dbdc6dfafafd9f60", "to": "FIG-11d27b7d197d5d54", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
